(async () => {
  const target = (await (await fetch('http://127.0.0.1:9222/json')).json()).find(x => x.url === 'http://127.0.0.1:3002/');
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let id = 0;
  const pending = new Map();
  ws.onmessage = event => { const m = JSON.parse(event.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
  const send = (method, params = {}) => new Promise(resolve => { const n = ++id; pending.set(n, resolve); ws.send(JSON.stringify({id:n,method,params})); }));
  const evaluate = async expression => (await send('Runtime.evaluate', {expression, returnByValue:true})).result.result.value;
  await send('Emulation.setDeviceMetricsOverride', {width:390,height:844,deviceScaleFactor:1,mobile:true});
  await send('Emulation.setTouchEmulationEnabled', {enabled:true,maxTouchPoints:5});
  const before = await evaluate("({width:innerWidth, controls:getComputedStyle(document.querySelector('.touch-controls')).display, joystick:!!document.querySelector('#stickZone'), fire:!!document.querySelector('#shootButton'), parry:!!document.querySelector('#parryButton')})");
  await evaluate("document.querySelector('#startButton').click()");
  await evaluate("document.querySelector('#parryButton').dispatchEvent(new PointerEvent('pointerdown',{pointerId:7,pointerType:'touch',bubbles:true}))");
  const after = await evaluate("({state:document.querySelector('#playerState').textContent, cooldown:document.querySelector('#parryButton small').textContent, overlayHint:!!document.querySelector('#overlayHint')})");
  console.log(JSON.stringify({before,after}, null, 2));
  ws.close();
})().catch(err => { console.error(err); process.exitCode = 1; });
